python3 - <<'EOF'
import os,re
root='/challenge/inhere'
for dp,_,fns in os.walk(root):
    for fn in sorted(fns):
        p=os.path.join(dp,fn)
        b=open(p,'rb').read()
        m=re.match(rb'(record \d\d-\d\d\n)', b)
        ok=False
        if m:
            unit=m.group(1)
            n=len(b)//len(unit)
            if b[:n*len(unit)]==unit*n and unit.startswith(b[n*len(unit):]):
                ok=True
        if set(b)<={0x78} or set(b)<={0}:
            ok=True
        if not ok:
            print("DEVIANT:",p,len(b))
EOF

